from __future__ import annotations

from pathlib import Path

from menai_benchmark import BenchmarkCase, BenchmarkSuite, MenaiProgram

_SUITE_DIR = Path(__file__).resolve().parent
_FIXTURES_DIR = _SUITE_DIR / "fixtures"

# Fixtures are generated by generate_fixtures.py and committed so every run
# reads byte-identical inputs.
_FIXTURE_NAMES = [
    "greyscale-64x64.png",
    "greyscale-alpha-64x64.png",
    "palette-128x128.png",
    "truecolour-128x128.png",
    "truecolour-alpha-128x128.png",
    "truecolour-192x192.png",
]

_ITERATIONS = 5

_EXPR = '(let ((png (import "png-decode"))) ((:: png decode) (dict-get inputs "input-data")))'


class Suite(BenchmarkSuite):
    """Benchmark suite for the Menai PNG decoder."""

    name = "png-decode"
    description = "Decode non-interlaced 8-bit PNG files of various colour types and sizes."

    def cases(self) -> list[BenchmarkCase]:
        """Return one case per fixture file."""
        return [
            BenchmarkCase(
                name=name.removesuffix(".png"),
                input=_FIXTURES_DIR / name,
                iterations=_ITERATIONS,
            )
            for name in _FIXTURE_NAMES
        ]

    def menai_program(self) -> MenaiProgram:
        """Return the PNG decode expression, reading fixture bytes as its input."""
        return MenaiProgram(
            expression=_EXPR,
            fixture=lambda fixture_path: fixture_path.read_bytes(),
        )
